{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import { isValidDueDate } from './public/dates.js';
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const databasePath = process.env.DB_PATH || './data/workboard.sqlite';
mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const updateProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const updateDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX IF NOT EXISTS tasks_by_project ON tasks(project_id, id)`);
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'notes')) {
  db.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'deleted')) {
  db.exec('ALTER TABLE tasks ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'position')) {
  db.exec('ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0; UPDATE tasks SET position = id');
}
// Keep positions reserved even while a task belongs to another project.
// Seed existing tasks with their current positions when upgrading a database.
db.exec(`CREATE TABLE IF NOT EXISTS task_positions (
  task_id INTEGER NOT NULL REFERENCES tasks(id),
  project_id INTEGER NOT NULL REFERENCES projects(id),
  position INTEGER NOT NULL,
  PRIMARY KEY (task_id, project_id)
);
CREATE INDEX IF NOT EXISTS task_positions_by_project ON task_positions(project_id, position);
INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
  SELECT id, project_id, position FROM tasks`);
const projectQuery = `SELECT projects.id, projects.name, projects.archived, projects.default_priority AS defaultPriority,
  COUNT(tasks.id) AS totalCount, COALESCE(SUM(tasks.completed), 0) AS completedCount
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id AND tasks.deleted = 0`;
const listProjects = db.prepare(`${projectQuery} GROUP BY projects.id ORDER BY projects.id`);
const findProject = db.prepare(`${projectQuery} WHERE projects.id = ? GROUP BY projects.id`);
const projectData = project => ({ ...project, archived: Boolean(project.archived) });
const listTasks = db.prepare('SELECT id, title, completed, priority, due_date AS dueDate, notes, deleted FROM tasks WHERE project_id = ? ORDER BY position, id');
const findTask = db.prepare('SELECT id, title, completed, priority, due_date AS dueDate, notes, deleted FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare(`INSERT INTO tasks (project_id, title, priority, position)
  VALUES (?, ?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM task_positions WHERE project_id = ?))`);
const rememberCreatedPosition = db.prepare(`INSERT INTO task_positions (task_id, project_id, position)
  SELECT id, project_id, position FROM tasks WHERE id = ?`);
const rememberDestinationPosition = db.prepare(`INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
  VALUES (?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM task_positions WHERE project_id = ?))`);
const moveTask = db.prepare(`UPDATE tasks SET project_id = ?,
  position = (SELECT position FROM task_positions WHERE project_id = ? AND task_id = ?)
  WHERE project_id = ? AND id = ?`);
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const updatePriority = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const updateDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
const updateNotes = db.prepare('UPDATE tasks SET notes = ? WHERE project_id = ? AND id = ?');
const updateDeleted = db.prepare('UPDATE tasks SET deleted = ? WHERE project_id = ? AND id = ?');
const taskData = task => ({ ...task, completed: Boolean(task.completed), deleted: Boolean(task.deleted) });

function transaction(action) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = action();
    db.exec('COMMIT');
    return result;
  } catch (error) {
    db.exec('ROLLBACK');
    throw error;
  }
}
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/dates.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/dates.js', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readBody(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
  }
}

const server = http.createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (request.method === 'GET' && path === '/api/projects') {
      return json(response, 200, listProjects.all().map(projectData));
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (request.method === 'GET' && projectMatch) {
      const project = findProject.get(projectMatch[1]);
      return json(response, project ? 200 : 404, project ? projectData(project) : { error: 'Project not found' });
    }
    if (request.method === 'PATCH' && projectMatch) {
      if (!findProject.get(projectMatch[1])) return json(response, 404, { error: 'Project not found' });
      const input = await readBody(request);
      const hasName = Object.hasOwn(input ?? {}, 'name');
      const hasArchive = Object.hasOwn(input ?? {}, 'archived');
      const hasDefaultPriority = Object.hasOwn(input ?? {}, 'defaultPriority');
      if ((!hasName && !hasArchive && !hasDefaultPriority) || (hasArchive && typeof input.archived !== 'boolean')) {
        return json(response, 400, { error: 'Archive state must be a boolean' });
      }
      if ((hasName || hasDefaultPriority) && findProject.get(projectMatch[1]).archived) {
        return json(response, 409, { error: 'Archived project' });
      }
      if (hasDefaultPriority && !['Low', 'Normal', 'High'].includes(input.defaultPriority)) {
        return json(response, 400, { error: 'Default task priority must be Low, Normal, or High' });
      }
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (hasName) {
        if (!name) return json(response, 400, { error: 'Project name is required' });
        renameProject.run(name, projectMatch[1]);
      }
      if (hasArchive) updateProject.run(Number(input.archived), projectMatch[1]);
      if (hasDefaultPriority) updateDefaultPriority.run(input.defaultPriority, projectMatch[1]);
      return json(response, 200, projectData(findProject.get(projectMatch[1])));
    }
    if (request.method === 'POST' && path === '/api/projects') {
      const input = await readBody(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(response, 201, projectData(findProject.get(Number(result.lastInsertRowid))));
    }
    const deletionMatch = path.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/(delete|restore)$/);
    if (request.method === 'POST' && deletionMatch) {
      const [, projectId, taskId, action] = deletionMatch;
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (project.archived) return json(response, 409, { error: 'Archived project' });
      if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
      updateDeleted.run(Number(action === 'delete'), projectId, taskId);
      return json(response, 200, taskData(findTask.get(projectId, taskId)));
    }
    const moveMatch = path.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/move$/);
    if (request.method === 'POST' && moveMatch) {
      const [, projectId, taskId] = moveMatch;
      const input = await readBody(request);
      const source = findProject.get(projectId);
      if (!source) return json(response, 404, { error: 'Project not found' });
      if (source.archived) return json(response, 409, { error: 'Archived project' });
      const task = findTask.get(projectId, taskId);
      if (!task) return json(response, 404, { error: 'Task not found' });
      if (task.deleted) return json(response, 409, { error: 'Deleted task' });
      if (!Number.isSafeInteger(input?.destinationProjectId) || input.destinationProjectId < 1 ||
          input.destinationProjectId === Number(projectId)) {
        return json(response, 400, { error: 'Choose another active destination project' });
      }
      const destination = findProject.get(input.destinationProjectId);
      if (!destination) return json(response, 404, { error: 'Destination project not found' });
      if (destination.archived) return json(response, 409, { error: 'Archived project' });
      transaction(() => {
        rememberDestinationPosition.run(taskId, destination.id, destination.id);
        moveTask.run(destination.id, destination.id, taskId, projectId, taskId);
      });
      return json(response, 200, taskData(findTask.get(destination.id, taskId)));
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'GET' && !taskId) {
        return json(response, 200, listTasks.all(projectId).map(taskData));
      }
      if (request.method === 'POST' && !taskId) {
        if (project.archived) return json(response, 409, { error: 'Archived project' });
        const input = await readBody(request);
        const currentProject = findProject.get(projectId);
        if (currentProject.archived) return json(response, 409, { error: 'Archived project' });
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const result = transaction(() => {
          const inserted = insertTask.run(projectId, title, currentProject.defaultPriority, projectId);
          rememberCreatedPosition.run(inserted.lastInsertRowid);
          return inserted;
        });
        return json(response, 201, taskData(findTask.get(projectId, Number(result.lastInsertRowid))));
      }
      if (request.method === 'PATCH' && taskId) {
        if (project.archived) return json(response, 409, { error: 'Archived project' });
        if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const input = await readBody(request);
        if (findProject.get(projectId).archived) return json(response, 409, { error: 'Archived project' });
        if (findTask.get(projectId, taskId).deleted) return json(response, 409, { error: 'Deleted task' });
        const hasTitle = Object.hasOwn(input ?? {}, 'title');
        const hasCompletion = Object.hasOwn(input ?? {}, 'completed');
        const hasPriority = Object.hasOwn(input ?? {}, 'priority');
        const hasDueDate = Object.hasOwn(input ?? {}, 'dueDate');
        const hasNotes = Object.hasOwn(input ?? {}, 'notes');
        if ((!hasTitle && !hasCompletion && !hasPriority && !hasDueDate && !hasNotes) || (hasCompletion && typeof input.completed !== 'boolean')) {
          return json(response, 400, { error: 'Completion must be a boolean' });
        }
        if (hasNotes && typeof input.notes !== 'string') {
          return json(response, 400, { error: 'Task notes must be text' });
        }
        if (hasPriority && !['Low', 'Normal', 'High'].includes(input.priority)) {
          return json(response, 400, { error: 'Task priority must be Low, Normal, or High' });
        }
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (hasTitle && !title) return json(response, 400, { error: 'Task title is required' });
        const dueDate = typeof input?.dueDate === 'string' ? input.dueDate.trim() : null;
        if (hasDueDate && (dueDate === null || !isValidDueDate(dueDate))) {
          return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
        }
        if (hasTitle) renameTask.run(title, projectId, taskId);
        if (hasCompletion) updateTask.run(Number(input.completed), projectId, taskId);
        if (hasPriority) updatePriority.run(input.priority, projectId, taskId);
        if (hasDueDate) updateDueDate.run(dueDate, projectId, taskId);
        if (hasNotes) updateNotes.run(input.notes, projectId, taskId);
        return json(response, 200, taskData(findTask.get(projectId, taskId)));
      }
    }
    if (request.method === 'GET') {
      const asset = assets.get(/^\/projects\/\d+$/.test(path) ? '/' : path);
      if (asset) {
        response.writeHead(200, { 'Content-Type': asset[0] });
        return response.end(asset[1]);
      }
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(response, error.status, { error: error.message });
    console.error(error);
    if (!response.headersSent) json(response, 500, { error: 'Unable to complete request' });
    else response.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => {
    db.close();
    process.exit(0);
  }));
}
import { isValidDueDate } from './dates.js';

const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function showError(container, message) {
  container.textContent = message;
  container.hidden = false;
}

function normalizeSearch(value) {
  return value.replace(/[ \t]+/g, ' ').replace(/[A-Z]/g, letter => letter.toLowerCase());
}

function projectRow(project, changeArchive) {
  const row = document.createElement('div');
  row.className = 'project-row';
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const open = document.createElement('button');
  open.type = 'button';
  open.textContent = 'Open project';
  open.addEventListener('click', () => location.assign(`/projects/${project.id}`));
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
  const archive = document.createElement('button');
  archive.type = 'button';
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', () => changeArchive(project, archive));
  row.append(name, summary, open, archive);
  return row;
}

async function renderProject(projectId) {
  app.innerHTML = `
    <button type="button" id="projects">Projects</button>
    <h1></h1>
    <p id="archived-notice" hidden>Archived project</p>
    <form id="rename-project">
      <label for="new-project-name">New project name</label>
      <div class="create-fields">
        <input id="new-project-name" name="name" type="text" autocomplete="off" disabled>
        <button type="submit" disabled>Rename project</button>
      </div>
    </form>
    <div class="task-filter">
      <label for="default-task-priority">Default task priority</label>
      <select id="default-task-priority" disabled>
        <option>Low</option><option selected>Normal</option><option>High</option>
      </select>
    </div>
    <form id="create-task">
      <label for="task-title">Task title</label>
      <div class="create-fields">
        <input id="task-title" name="title" type="text" autocomplete="off">
        <button type="submit" disabled>Create task</button>
      </div>
    </form>
    <p role="alert" hidden></p>
    <div class="task-filter">
      <label for="task-filter">Task filter</label>
      <select id="task-filter">
        <option>All</option><option>Open</option><option>Completed</option><option>Deleted</option>
      </select>
    </div>
    <div class="task-filter">
      <label for="priority-filter">Priority filter</label>
      <select id="priority-filter">
        <option>All</option><option>Low</option><option>Normal</option><option>High</option>
      </select>
    </div>
    <form id="due-range" class="task-filter">
      <label for="due-from">Due from</label>
      <input id="due-from" type="text" autocomplete="off">
      <label for="due-through">Due through</label>
      <input id="due-through" type="text" autocomplete="off">
      <button type="submit">Apply due range</button>
    </form>
    <form id="task-search-form" class="task-filter">
      <label for="task-search">Task search</label>
      <div class="create-fields">
        <input id="task-search" type="text" autocomplete="off">
        <button type="submit">Search tasks</button>
      </div>
    </form>
    <section aria-label="Tasks" id="task-list"></section>`;
  app.querySelector('#projects').addEventListener('click', () => location.assign('/'));
  const form = app.querySelector('#create-task');
  const renameForm = app.querySelector('#rename-project');
  const renameInput = app.querySelector('#new-project-name');
  const renameButton = renameForm.querySelector('button');
  const input = app.querySelector('#task-title');
  const button = form.querySelector('button');
  const alert = app.querySelector('[role="alert"]');
  const filter = app.querySelector('#task-filter');
  const priorityFilter = app.querySelector('#priority-filter');
  const defaultPriority = app.querySelector('#default-task-priority');
  const dueRangeForm = app.querySelector('#due-range');
  const dueFrom = app.querySelector('#due-from');
  const dueThrough = app.querySelector('#due-through');
  let appliedFrom = '';
  let appliedThrough = '';
  const searchForm = app.querySelector('#task-search-form');
  const searchInput = app.querySelector('#task-search');
  let appliedSearch = '';
  const list = app.querySelector('#task-list');
  const tasksPath = `/api/projects/${projectId}/tasks`;
  let tasks = [];
  let destinations = [];
  let archived = false;
  let savedDefaultPriority;

  function displayTasks() {
    const matching = tasks.filter(task =>
      normalizeSearch(task.title).includes(appliedSearch) &&
      (filter.value === 'Deleted' ? task.deleted : !task.deleted &&
        (filter.value === 'All' || (filter.value === 'Completed' ? task.completed : !task.completed))) &&
      (priorityFilter.value === 'All' || task.priority === priorityFilter.value) &&
      ((!appliedFrom && !appliedThrough) || (task.dueDate &&
        (!appliedFrom || task.dueDate >= appliedFrom) &&
        (!appliedThrough || task.dueDate <= appliedThrough))));
    list.replaceChildren(...matching.map(task => {
      const readOnly = archived || Boolean(task.deleted);
      const row = document.createElement('div');
      row.className = 'task-row';
      row.dataset.testid = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = readOnly;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        if (readOnly) return;
        checkbox.disabled = true;
        alert.hidden = true;
        try {
          const saved = await request(`${tasksPath}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          Object.assign(task, saved);
          displayTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showError(alert, error.message);
        } finally {
          checkbox.disabled = readOnly;
        }
      });
      const renameForm = document.createElement('form');
      renameForm.className = 'rename-task';
      const renameLabel = document.createElement('label');
      renameLabel.textContent = 'New task title';
      const renameInput = document.createElement('input');
      renameInput.id = `new-task-title-${task.id}`;
      renameInput.type = 'text';
      renameInput.name = 'title';
      renameInput.autocomplete = 'off';
      renameInput.disabled = readOnly;
      renameLabel.htmlFor = renameInput.id;
      const renameButton = document.createElement('button');
      renameButton.type = 'submit';
      renameButton.textContent = 'Rename task';
      renameButton.disabled = readOnly;
      const fields = document.createElement('div');
      fields.className = 'create-fields';
      fields.append(renameInput, renameButton);
      renameForm.append(renameLabel, fields);
      renameForm.addEventListener('submit', async event => {
        event.preventDefault();
        if (readOnly) return;
        const newTitle = renameInput.value.trim();
        if (!newTitle) {
          showError(alert, 'Task title is required');
          renameInput.focus();
          return;
        }
        renameButton.disabled = true;
        alert.hidden = true;
        try {
          const saved = await request(`${tasksPath}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title: newTitle }),
          });
          Object.assign(task, saved);
          title.textContent = task.title;
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          renameInput.value = '';
          renameInput.focus();
          if (appliedSearch) displayTasks();
        } catch (error) {
          showError(alert, error.message);
        } finally {
          renameButton.disabled = readOnly;
        }
      });
      const priorityField = document.createElement('div');
      const priorityLabel = document.createElement('label');
      priorityLabel.textContent = 'Task priority';
      const priority = document.createElement('select');
      priority.id = `task-priority-${task.id}`;
      priorityLabel.htmlFor = priority.id;
      for (const value of ['Low', 'Normal', 'High']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        priority.append(option);
      }
      priority.value = task.priority;
      priority.disabled = readOnly;
      priority.addEventListener('change', async () => {
        if (readOnly) return;
        priority.disabled = true;
        alert.hidden = true;
        try {
          const saved = await request(`${tasksPath}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ priority: priority.value }),
          });
          Object.assign(task, saved);
          displayTasks();
        } catch (error) {
          priority.value = task.priority;
          showError(alert, error.message);
        } finally {
          priority.disabled = readOnly;
        }
      });
      priorityField.append(priorityLabel, priority);
      const dueDateForm = document.createElement('form');
      dueDateForm.className = 'task-due-date';
      const dueDateLabel = document.createElement('label');
      dueDateLabel.textContent = 'Task due date';
      const dueDateInput = document.createElement('input');
      dueDateInput.id = `task-due-date-${task.id}`;
      dueDateInput.type = 'text';
      dueDateInput.autocomplete = 'off';
      dueDateInput.value = task.dueDate;
      dueDateInput.disabled = readOnly;
      dueDateLabel.htmlFor = dueDateInput.id;
      const dueDateButton = document.createElement('button');
      dueDateButton.type = 'submit';
      dueDateButton.textContent = 'Save due date';
      dueDateButton.disabled = readOnly;
      const dueDateFields = document.createElement('div');
      dueDateFields.className = 'create-fields';
